<template><PageShell title="Fleet Availability" subtitle="City-wide view of ambulance operational status, readiness, and credential condition." icon="lucide:ambulance" eyebrow="Platform Executive"><template #actions><LiveBadge :live="live" /></template><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Fleet units" :value="stats.total"/><Stat label="Available" :value="stats.available"/><Stat label="Active mission" :value="stats.active_mission"/><Stat label="Maintenance / Offline" :value="stats.maintenance"/></div><section class="mt-6 overflow-hidden rounded-3xl border border-base-300 bg-base-100 shadow-sm dark:border-white/10 dark:bg-[#071829]"><div v-if="loading" class="py-20 text-center text-sm text-slate-400">Loading fleet...</div><div v-else class="overflow-x-auto"><table class="w-full min-w-[1000px] text-left text-sm"><thead class="bg-base-200/70 text-[.66rem] font-black uppercase text-slate-400"><tr><th class="px-5 py-3">Unit</th><th class="px-5 py-3">Organization</th><th class="px-5 py-3">Type</th><th class="px-5 py-3">Operational</th><th class="px-5 py-3">Readiness</th><th class="px-5 py-3">Credentials</th></tr></thead><tbody class="divide-y divide-base-300 dark:divide-white/5"><tr v-for="u in items" :key="u.id"><td class="px-5 py-4"><p class="font-black dark:text-white">{{ u.unit_code }}</p><p class="text-xs text-slate-400">{{ u.plate_number }}</p></td><td class="px-5 py-4 font-bold text-slate-600 dark:text-white/60">{{ u.organization_name }}</td><td class="px-5 py-4 text-xs">{{ pretty(u.ambulance_type) }}</td><td class="px-5 py-4"><span class="rounded-full bg-base-200 px-2.5 py-1 text-xs font-black">{{ pretty(u.status) }}</span></td><td class="px-5 py-4"><span class="text-xs font-bold" :class="u.readiness_status==='ready'?'text-emerald-600':'text-amber-600'">{{ pretty(u.readiness_status||'not_checked') }}</span></td><td class="px-5 py-4 text-xs text-slate-500">Reg {{ u.registration_expiry||'—' }}<br/>Inspection {{ u.inspection_expiry||'—' }}</td></tr></tbody></table></div></section></PageShell></template>
<script setup>import{defineComponent,h,onMounted,ref}from'vue';import PageShell from '@/components/management/PageShell.vue';import{fetchPlatformFleet}from'@/services/adminCompletion';import{useLiveUpdates}from'@/composables/useLiveUpdates';import{realtimeChannels}from'@/services/realtime';import LiveBadge from '@/components/realtime/LiveBadge.vue';const items=ref([]),stats=ref({}),loading=ref(false);const Stat=defineComponent({props:{label:String,value:[String,Number]},setup:p=>()=>h('article',{class:'rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]'},[h('p',{class:'text-2xl font-black dark:text-white'},String(p.value??0)),h('p',{class:'mt-1 text-xs font-bold text-slate-500'},p.label)])});const pretty=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase());async function load(silent=false){if(!silent)loading.value=true;try{const d=await fetchPlatformFleet();items.value=d.items||[];stats.value=d.stats||{}}finally{loading.value=false}};const{live}=useLiveUpdates(load,{channels:()=>[realtimeChannels.value?.platform],events:['fleet.updated','mission.updated'],debounceMs:600,pollMs:30000,livePollMs:120000});onMounted(()=>load())</script>
